	}
}

func TestThemeDarkAndLightRoundTrip(t *testing.T) {
	loaded, reloaded, saved := roundTrip(t, "app:\n  theme: auto\n  theme_dark: nord\n  theme_light: solarized-light\n")
	for _, cfg := range []*Config{loaded, reloaded} {
